function equipCosmetic(confirm=false){if(menuScreen!=='shop'||cosmeticTab==='ship')return;if(challengeCosmeticLocked(cosmeticTab,cosmeticSelection))return;const type=cosmeticTab,id=cosmeticSelection,load=data.cosmetics[type],owned=load.owned.includes(id),cost=cosmeticCatalog[type][id][1];if(load.equipped===id||!owned&&(!confirm||cosmeticPending!==id||data.coins<cost))return;const previous=JSON.stringify(data.cosmetics),balance=data.coins;if(!owned){data.coins-=cost;load.owned.push(id)}load.equipped=id;save();if(!storageOK){data.cosmetics=JSON.parse(previous);data.coins=balance;shopMessage=shopWords()[15]}else shopMessage=shopWords()[owned?14:13];cosmeticPending=null;wallet();renderShopInterface()}
const cosmeticShipAction=$('shopAction').onclick,cosmeticShipAccept=$('shopAccept').onclick,cosmeticShipCancel=$('shopCancel').onclick;
$('shopAction').onclick=()=>{if(cosmeticTab==='ship')return cosmeticShipAction();if(menuScreen!=='shop'||challengeCosmeticLocked(cosmeticTab,cosmeticSelection))return;if(data.cosmetics[cosmeticTab].owned.includes(cosmeticSelection))equipCosmetic();else if(data.coins>=cosmeticCatalog[cosmeticTab][cosmeticSelection][1]){cosmeticPending=cosmeticSelection;renderShopInterface()}};
$('shopAccept').onclick=()=>cosmeticTab==='ship'?cosmeticShipAccept():equipCosmetic(true);$('shopCancel').onclick=()=>{if(cosmeticTab==='ship')return cosmeticShipCancel();cosmeticPending=null;renderShopInterface()};
for(const type of ['ship','flame','trail','paint','coins'])$('shopTab'+type).onclick=()=>{cosmeticTab=type;cosmeticSelection=type==='ship'||type==='coins'?0:data.cosmetics[type].equipped;cosmeticPending=null;shopPending=null;shopMessage='';renderShopInterface()};
const cosmeticMenu=showMenu;showMenu=function(tab='main'){cosmeticPending=null;if(tab==='shop'&&menuScreen!=='shop'){cosmeticTab='ship';normalizeCosmetics()}return cosmeticMenu(...arguments)};
const cosmeticBackupValidator=validateBackup;validateBackup=function(raw){const out=cosmeticBackupValidator(raw),input=raw.game.cosmetics||{};out.game.cosmetics={};for(const type of ['flame','trail','paint']){const v=input[type]||{},owned=Array.isArray(v.owned)?[...new Set(v.owned.filter(i=>Number.isInteger(i)&&cosmeticCatalog[type][i]))]:[0];if(!owned.includes(0))owned.unshift(0);out.game.cosmetics[type]={owned,equipped:owned.includes(v.equipped)?v.equipped:0}}return out};


function cosmeticShipSkin(id){if(globalThis.starwayChallengesReady&&challengeActive)return skins[0];const base=skins[id],index=cosmeticChoice('paint'),paint=cosmeticCatalog.paint[index];if(!paint||!index)return base;const next=base.slice();next[2]=paint[2];next[3]=paint[3];return next}
