function renderCoinShop(){const grid=$('shopgrid');grid.innerHTML='';grid.style.gridTemplateRows='repeat(4,minmax(44px,1fr))';for(const product of coinProducts){const info=revenueProvider?.products?.[product.id],b=document.createElement('button');b.className='coin-product';b.textContent='◈ '+product.title+' · '+(info?.priceLabel||'판매 준비 중');b.disabled=!info||!revenueProvider?.purchase||!revenueProvider?.verifyPurchase||revenueBusy;b.onclick=async()=>{if(b.disabled)return;b.disabled=true;await buyCoinProduct(product.id);renderShopInterface()};grid.appendChild(b)}const restore=document.createElement('button');restore.className='coin-product';restore.textContent='구매 복원';restore.disabled=!revenueProvider?.restorePurchases||revenueBusy;restore.onclick=async()=>{await restoreRevenuePurchases();renderShopInterface()};grid.appendChild(restore);$('shopState').textContent='COINS';$('shopName').textContent='코인 구매';$('shopNote').textContent='';$('shopFairness').textContent='';$('shopBalance').textContent='현재 결제 서비스가 연결되지 않았습니다. 코인은 플레이로 모을 수 있습니다.';$('shopStatus').textContent=$('revenueStatus').textContent||'';$('shopAction').classList.add('hidden');$('shopConfirm').classList.add('hidden');}
